/** One artwork in the gallery. Generated by `deno task migrate`. */
export interface Artwork {
  /** Stable short-uuid id, also the image filename stem. */
  id: string;
  category: string;
  description: string;
  image: string;
  thumb: string;
  width: number;
  height: number;
  thumbWidth: number;
  thumbHeight: number;
  /** Source path in the legacy CMS, kept for provenance. */
  legacy: string;
}
